begin;select plan(7);select has_table('public','admin_rate_limits','rate table');select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.admin_rate_limits'::regclass),'forced RLS');select is((select count(*) from information_schema.role_table_grants where table_name='admin_rate_limits' and grantee in('anon','authenticated')),0::bigint,'no browser grants');select ok(not has_function_privilege('anon','public.consume_admin_rate_limit(text,text,integer,integer)','execute'),'anon no execute');select ok(not has_function_privilege('authenticated','public.consume_admin_rate_limit(text,text,integer,integer)','execute'),'authenticated no execute');select throws_ok($$select * from consume_admin_rate_limit('bad','unknown',1,1)$$,'22023','INVALID_RATE_LIMIT_INPUT','invalid fails');select ok(has_function_privilege('persi_app','public.consume_admin_rate_limit(text,text,integer,integer)','execute'),'server execute');select * from finish();rollback;
